<script lang="ts">import { untrack, type Snippet } from 'svelte'; import type { ToastManager } from './create-toast-manager.js'; import { ToastProviderState, setToastProviderContext } from './toast-context.svelte.js'; interface Props { children?: Snippet; timeout?: number; limit?: number; toastManager?: ToastManager; } let { children, timeout = 5000, limit = 3, toastManager }: Props = $props(); const provider = setToastProviderContext(new ToastProviderState()); $effect.pre(() => { provider.timeout = timeout; provider.limit = limit; untrack(() => provider.applyLimit()); }); $effect(() => { if (!toastManager) return; return toastManager[' subscribe'](({ action, options }) => { if (action === 'add') provider.add(options); if (action === 'close') provider.close(options.id); if (action === 'update') provider.update(options.id, options); if (action === 'promise') provider.promise(options.promise, options); }); });</script>{@render children?.()}
